        <script>
                (async function () {
                    const ul = document.querySelector('.my-deputat__list');
                    if (!ul) return;
                    const res = await fetch('/candidates?format=json&limit=8');
                    const data = await res.json();
                    const tpl = (c) => `
                        <li class="my-deputat__item">
                            <div class="my-deputat__image-wrap">
                                <a href="/candidate?id=${Number(c.id)}">
                                    <img
                                        class="my-deputat__image"
                                        src="${c.photo ? c.photo : '/assets/img/candidates/placeholder.jpeg'}"
                                        alt="${(c.surname || '') + ' ' + (c.name || '') + ' ' + (c.patronymic || '')}"
                                        width="161" height="242">
                                </a>
                                <a class="vote-btn" data-id="${c.id}" href="#">Проголосовать</a>
                            </div>
                            <a href="/candidate?id=${Number(c.id)}" class="my-deputat__name">
                                ${(c.surname || '') + ' ' + (c.name || '') + ' ' + (c.patronymic || '')}
                            </a>
                            <a href="/candidate?id=${Number(c.id)}" class="my-deputat__post">Кандидат Молодёжной Думы</a>
                            <a href="/candidate?id=${Number(c.id)}" class="my-deputat__district">Округ ${(c.district || '')}</a>
                            <a href="mailto:${c.email}" class="my-deputat__email">${(c.email || '')}</a>
                        </li>`;
                    ul.innerHTML = data.map(tpl).join('');
                })();
        </script>
        <script src="/js/load-modals.js"></script>
        <script src="/js/message-modal.js"></script>
        <script src="/js/modals.js"></script>
        <script>
            // Эта функция вызывается, когда Гугловский скрипт reCAPTCHA загружен
            function onRecaptchaLoad() {
                console.log('onRecaptchaLoad: API загружен. grecaptcha =', !!window.grecaptcha);

                // Ждём чуть-чуть, чтобы модалки точно успели подгрузиться
                setTimeout(() => {
                    const el = document.querySelector('.g-recaptcha');
                    console.log('onRecaptchaLoad: найден .g-recaptcha?', !!el);

                    if (el && window.grecaptcha) {
                        // Если что-то уже отрисовано — не рендерим второй раз
                        if (!el.hasChildNodes()) {
                            console.log('onRecaptchaLoad: рендерим виджет reCAPTCHA');
                            window.grecaptcha.render(el);
                        } else {
                            console.log('onRecaptchaLoad: у .g-recaptcha уже есть дети (iframe?)');
                        }
                    } else {
                        console.log('onRecaptchaLoad: либо нет grecaptcha, либо нет div.g-recaptcha');
                    }
                }, 300);
            }

            // На всякий случай ещё раз проверим чуть позже (если модалки загрузились с задержкой)
            window.addEventListener('load', () => {
                setTimeout(() => {
                    const el = document.querySelector('.g-recaptcha');
                    console.log('window.load: повторная проверка .g-recaptcha =', !!el);
                    if (el && window.grecaptcha && !el.hasChildNodes()) {
                        console.log('window.load: рендерим reCAPTCHA повторно');
                        window.grecaptcha.render(el);
                    }
                }, 800);
            });
        </script>
        <script src="https://www.google.com/recaptcha/api.js" async defer></script>
        <script src="https://unpkg.com/@vkid/sdk@3.0.0/dist-sdk/umd/index.js"></script>
        <script src="./js/vk-auth.js"></script>
        <script src="https://ugd.ru/local/templates/ugd/js/swiper-bundle.min.js"></script>
        <script src="https://ugd.ru/local/templates/ugd/js/script.min.js"></script>
        <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
        <script src="https://ugd.ru/local/templates/ugd/js/fancybox.umd.js"></script>
        <script>
            Fancybox.bind('[data-fancybox="gallery"]', {
                infinite: false
            });
        </script>
